            'Contact Email Address' => 'Email de contacto',
            'Contact Phone Number' => 'Telefono de contacto',
            'Add Supplier' => 'Agregar proveedor',
            'Registered Component Suppliers' => 'Proveedores de componentes registrados',
            'Supplier Name' => 'Nombre proveedor',
            'Contact Email' => 'Email contacto',
            'PO ID' => 'ID OC',
            'Supplier' => 'Proveedor',
