            'Supplier name is required.' => 'El nombre del proveedor es obligatorio.',
            'Please select a valid supplier and specify a total cost.' => 'Selecciona un proveedor valido e indica un costo total.',
        ],
    ];

    $baseMap = $maps[$locale] ?? [];
    $homeMap = i18n_home_phrase_map($locale);
    $builderMap = i18n_builder_phrase_map($locale);
    $runtimeMap = i18n_builder_runtime_phrase_map($locale);
    
    require_once __DIR__ . '/i18n_missing.php';
    $missingMap = i18n_missing_phrase_map($locale);

    return array_merge($baseMap, $homeMap, $builderMap, $runtimeMap, $missingMap);
}

