function i18n_start_page_translation(): void
{
    static $started = false;

    if (i18n_current_locale() === I18N_DEFAULT_LOCALE || headers_sent()) {
        return;
    }

    if ($started) {
        return;
    }

    $map = i18n_page_phrase_map();
    if ($map === []) {
        return;
    }

    $started = true;

    // Build a safe map: remove keys shorter than 4 chars
    // We KEEP identity mappings of length >= 4 to act as shields in strtr
    $safeMap = [];
    foreach ($map as $k => $v) {
        $keyLength = function_exists('mb_strlen') ? mb_strlen($k, 'UTF-8') : strlen($k);
        if ($keyLength < 4) continue;   // too short = dangerous substring
        $safeMap[$k] = $v;
    }

    ob_start(static function (string $html) use ($map, $safeMap): string {
        return preg_replace_callback(
            '/(<script\b[^>]*>.*?<\/script>|<style\b[^>]*>.*?<\/style>|<[^>]+>|[^<]+)/is',
            static function (array $m) use ($map, $safeMap): string {
                // Tags: translate specific attributes only
                if (str_starts_with($m[0], '<')) {
                    return i18n_translate_tag_attributes($m[0], $safeMap);
                }

                // Text node: try exact match on trimmed text first (safest)
                $raw = $m[0];
                $trimmed = trim($raw);
                if ($trimmed === '') return $raw;

                // Phase 1: exact full-node match (O(1) hashtable lookup)
                if (isset($map[$trimmed]) && $map[$trimmed] !== $trimmed) {
                    return str_replace($trimmed, $map[$trimmed], $raw);
                }

                return $raw;
            },
            $html
        ) ?? $html;
    });
}

function i18n_translate_tag_attributes(string $tag, array $map): string
{
    if ($map === [] || preg_match('/^<\/|^<(?:script|style)\b/i', $tag)) {
        return $tag;
    }

    return preg_replace_callback(
        '/\s(placeholder|title|aria-label|alt)\s*=\s*("|\')([^"\']*)\2/i',
        static function (array $m) use ($map): string {
            $val = $m[3];
            $trimmed = trim($val);
            if ($trimmed !== '' && isset($map[$trimmed]) && $map[$trimmed] !== $trimmed) {
                $val = str_replace($trimmed, $map[$trimmed], $val);
            }
            return ' ' . $m[1] . '=' . $m[2] . $val . $m[2];
        },
        $tag
    ) ?? $tag;
}

function i18n_language_switcher(string $class = 'nav-translate', string $style = ''): string
{
    $currentLocale = i18n_current_locale();
    $localeLabels = i18n_locale_labels();
    $styleAttr = $style !== '' ? ' style="' . htmlspecialchars($style, ENT_QUOTES, 'UTF-8') . '"' : '';
    $html = '<div class="custom-translate-container ' . htmlspecialchars($class, ENT_QUOTES, 'UTF-8') . '"' . $styleAttr . ' aria-label="' . htmlspecialchars(i18n_t('nav.select_language'), ENT_QUOTES, 'UTF-8') . '">';
    $html .= '<button class="custom-translate-btn notranslate" type="button" aria-label="' . htmlspecialchars(i18n_t('nav.select_language'), ENT_QUOTES, 'UTF-8') . '" aria-haspopup="true" aria-expanded="false" data-language-toggle>';
    $html .= htmlspecialchars(strtoupper($currentLocale), ENT_QUOTES, 'UTF-8');
    $html .= '</button><div class="custom-translate-dropdown" hidden data-language-menu>';

    foreach ($localeLabels as $locale => $label) {
        $active = $locale === $currentLocale ? ' active' : '';
        $html .= '<a class="custom-translate-option notranslate' . $active . '" href="' . htmlspecialchars(i18n_current_url_for($locale), ENT_QUOTES, 'UTF-8') . '" lang="' . htmlspecialchars($locale, ENT_QUOTES, 'UTF-8') . '">';
        $html .= '<span class="flag-icon">' . htmlspecialchars(strtoupper($locale), ENT_QUOTES, 'UTF-8') . '</span>';
        $html .= '<span class="lang-name">' . htmlspecialchars($label, ENT_QUOTES, 'UTF-8') . '</span>';
        $html .= '</a>';
    }

    return $html . '</div></div>';
}

function i18n_language_switcher_assets(): string
{
    return <<<'HTML'
<style>
    .custom-translate-container{position:relative;z-index:300;display:inline-flex;align-items:center;font-family:"Syne","Inter",system-ui,sans-serif}
    .custom-translate-btn{min-width:44px;height:34px;padding:0 12px;border:1px solid var(--border-cyan,var(--border,rgba(0,245,212,.28)));border-radius:8px;background:linear-gradient(135deg,rgba(0,245,212,.1),rgba(255,107,53,.05));color:var(--cyan,#00f5d4);font:800 .72rem/1 "Space Mono","JetBrains Mono",monospace;letter-spacing:0;cursor:pointer}
    .custom-translate-btn:hover,.custom-translate-btn:focus-visible,.custom-translate-container:focus-within .custom-translate-btn{border-color:var(--cyan,#00f5d4);background:rgba(0,245,212,.14);color:var(--white,var(--text,#eef0f4));outline:none}
    .custom-translate-dropdown{position:absolute;top:calc(100% + 8px);right:0;min-width:168px;padding:6px;border:1px solid var(--border-cyan,var(--border,rgba(0,245,212,.18)));border-radius:8px;background:var(--page-bg-2,var(--card-bg,#0a0b0e));box-shadow:0 18px 48px rgba(0,0,0,.38);opacity:0;transform:translateY(-6px);pointer-events:none;transition:opacity .18s ease,transform .18s ease}
    .custom-translate-dropdown[hidden]{display:none!important}
    .custom-translate-dropdown.show{opacity:1;transform:translateY(0);pointer-events:auto}
    .custom-translate-option{display:flex;align-items:center;gap:10px;width:100%;padding:9px 10px;border-radius:6px;background:transparent;color:var(--muted,var(--text-muted,#b0b8c8));font:700 .8rem/1.2 "Syne","Inter",system-ui,sans-serif;text-align:left;text-decoration:none;cursor:pointer}
    .custom-translate-option:hover,.custom-translate-option:focus-visible,.custom-translate-option.active{background:rgba(0,245,212,.09);color:var(--cyan,#00f5d4);outline:none}
    .custom-translate-option .flag-icon{min-width:28px;color:var(--cyan,#00f5d4);font-family:"Space Mono","JetBrains Mono",monospace;font-size:.7rem;font-weight:900;letter-spacing:0}
    [data-theme="light"] .custom-translate-btn,body.light-mode .custom-translate-btn{border-color:rgba(0,122,110,.22);background:linear-gradient(135deg,rgba(0,122,110,.08),rgba(198,93,36,.06));color:var(--industrial-teal,#007a6e)}
    [data-theme="light"] .custom-translate-dropdown,body.light-mode .custom-translate-dropdown{border-color:rgba(0,122,110,.16);background:var(--industrial-surface,#f6f7f4);box-shadow:0 18px 42px rgba(15,23,42,.14)}
    [dir="rtl"] .custom-translate-dropdown{right:auto;left:0}
</style>
HTML . i18n_preference_assets() . <<<'HTML'
<script>
    window.MarocPCInitLanguageSwitcher = window.MarocPCInitLanguageSwitcher || function () {
        document.querySelectorAll('[data-language-toggle]').forEach((button) => {
            const container = button.closest('.custom-translate-container');
            const menu = container ? container.querySelector('[data-language-menu]') : null;
            if (!menu || button.dataset.languageReady === '1') return;
            button.dataset.languageReady = '1';
            const close = () => { menu.hidden = true; menu.classList.remove('show'); button.setAttribute('aria-expanded', 'false'); };
            button.addEventListener('click', (event) => {
                event.stopPropagation();
                const open = menu.hidden;
                menu.hidden = !open;
                menu.classList.toggle('show', open);
                button.setAttribute('aria-expanded', String(open));
            });
            menu.addEventListener('click', (event) => event.stopPropagation());
            document.addEventListener('click', close);
            document.addEventListener('keydown', (event) => { if (event.key === 'Escape') close(); });
        });
    };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', window.MarocPCInitLanguageSwitcher);
    else window.MarocPCInitLanguageSwitcher();
</script>
HTML;
}

function i18n_preference_assets(): string
{
    $locale = i18n_current_locale();
    $supported = i18n_supported_locales();
    $phraseMap = i18n_page_phrase_map($locale);

    return '<script>window.__marocPcLocale=' . json_encode($locale, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . ';window.__marocPcSupportedLocales=' . json_encode($supported, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . ';window.__marocPcPhraseMap=Object.assign({},window.__marocPcPhraseMap||{},' . json_encode($phraseMap, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . ');</script>' . <<<'HTML'
<script>
    window.MarocPCInitLanguagePreference = window.MarocPCInitLanguagePreference || function () {
        const supported = Array.isArray(window.__marocPcSupportedLocales) ? window.__marocPcSupportedLocales : ['en', 'fr', 'ar', 'es'];
        const defaultLocale = 'en';
        const storageKey = 'marocpc_lang';
        const cookieName = 'marocpc_lang';
        const current = supported.includes(window.__marocPcLocale) ? window.__marocPcLocale : defaultLocale;
        const params = new URLSearchParams(window.location.search);
        const requested = params.get('lang');

        const readCookie = () => {
            const match = document.cookie.match(new RegExp('(?:^|; )' + cookieName + '=([^;]*)'));
            return match ? decodeURIComponent(match[1]) : '';
        };

        const writePreference = (locale) => {
            if (!supported.includes(locale)) return;
            try { localStorage.setItem(storageKey, locale); } catch (error) {}
            document.cookie = cookieName + '=' + encodeURIComponent(locale) + '; max-age=31536000; path=/; samesite=lax';
        };

        const preferred = supported.includes(requested)
            ? requested
            : (supported.includes(readCookie()) ? readCookie() : (() => {
                try {
                    const saved = localStorage.getItem(storageKey);
                    return supported.includes(saved) ? saved : current;
                } catch (error) {
                    return current;
                }
            })());

        writePreference(preferred);

        const shouldCarry = (url) => {
            if (url.origin !== window.location.origin) return false;
            if (/^(mailto|tel|sms|javascript):/i.test(url.protocol)) return false;
            const path = url.pathname.toLowerCase();
            return path.endsWith('.php') || path.endsWith('.html') || !/\.[a-z0-9]{2,8}$/i.test(path);
        };

        const syncUrl = (rawUrl) => {
            if (!rawUrl || rawUrl.startsWith('#')) return rawUrl;
            let url;
            try {
                url = new URL(rawUrl, window.location.href);
            } catch (error) {
                return rawUrl;
            }
            if (!shouldCarry(url)) return rawUrl;

            if (preferred === defaultLocale) {
                url.searchParams.delete('lang');
            } else {
                url.searchParams.set('lang', preferred);
            }

            return url.pathname + url.search + url.hash;
        };

        const syncLinks = (root = document) => {
            root.querySelectorAll?.('a[href]').forEach((link) => {
                if (link.closest('.custom-translate-dropdown')) return;
                const next = syncUrl(link.getAttribute('href'));
                if (next && next !== link.getAttribute('href')) link.setAttribute('href', next);
            });
        };

        const syncForms = (root = document) => {
            root.querySelectorAll?.('form').forEach((form) => {
                const method = (form.getAttribute('method') || 'get').toLowerCase();
                if (method !== 'get') return;
                const action = form.getAttribute('action') || window.location.pathname;
                const nextAction = syncUrl(action);
                if (nextAction && nextAction !== action) form.setAttribute('action', nextAction);

                let hidden = form.querySelector('input[type="hidden"][name="lang"]');
                if (preferred === defaultLocale) {
                    hidden?.remove();
                    return;
                }
                if (!hidden) {
                    hidden = document.createElement('input');
                    hidden.type = 'hidden';
                    hidden.name = 'lang';
                    form.prepend(hidden);
                }
                hidden.value = preferred;
            });
        };

        const syncLanguageOptions = () => {
            document.querySelectorAll('.custom-translate-option[lang]').forEach((option) => {
                option.addEventListener('click', () => writePreference((option.getAttribute('lang') || '').slice(0, 2)), { once: true });
            });
        };

        const initDynamicTranslation = () => {
            if (current === defaultLocale || window.__marocPcDynamicI18nReady === '1') return;
            const phraseMap = window.__marocPcPhraseMap || {};
            const entries = Object.entries(phraseMap)
                .filter(([source, target]) => source && target && source !== target && source.length >= 4)
                .sort((a, b) => b[0].length - a[0].length);
            if (!entries.length) return;

            window.__marocPcDynamicI18nReady = '1';
            const skipAttrSelector = '.notranslate,[translate="no"],script,style,noscript,template,.cc-name,.cc-brand,.cc-spec-tag,.product-name,.product-title,.brand-name,.money-token';
            const skipTextSelector = '.notranslate,[translate="no"],script,style,noscript,template,input,textarea,.cc-name,.cc-brand,.cc-spec-tag,.product-name,.product-title,.brand-name,.money-token';
            const translateValue = (value) => {
                if (!value || typeof value !== 'string') return value;
                const trimmed = value.trim();
                if (phraseMap[trimmed] && phraseMap[trimmed] !== trimmed) {
                    return value.replace(trimmed, phraseMap[trimmed]);
                }
                return value;
            };
            const translateAttributes = (element) => {
                if (!(element instanceof Element) || element.closest(skipAttrSelector)) return;
                ['placeholder', 'title', 'aria-label', 'alt', 'data-ai-prompt'].forEach((attribute) => {
                    if (!element.hasAttribute(attribute)) return;
                    const original = element.getAttribute(attribute);
                    const translated = translateValue(original);
                    if (translated !== original) element.setAttribute(attribute, translated);
                });
            };
            const translateText = (root) => {
                if (!root) return;
                if (root instanceof Element && !root.matches(skipAttrSelector)) translateAttributes(root);
                const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
                    acceptNode(node) {
                        const parent = node.parentElement;
                        if (!parent || parent.closest(skipTextSelector)) return NodeFilter.FILTER_REJECT;
                        return node.nodeValue && node.nodeValue.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
                    }
                });
                const nodes = [];
                while (walker.nextNode()) nodes.push(walker.currentNode);
                nodes.forEach((node) => {
                    const translated = translateValue(node.nodeValue);
                    if (translated !== node.nodeValue) node.nodeValue = translated;
                });
                if (root instanceof Element) {
                    root.querySelectorAll('[placeholder],[title],[aria-label],[alt],[data-ai-prompt]').forEach(translateAttributes);
                }
            };

            translateText(document.body);
            new MutationObserver((mutations) => {
                mutations.forEach((mutation) => {
                    mutation.addedNodes.forEach((node) => {
                        if (node.nodeType === Node.TEXT_NODE) {
                            const parent = node.parentElement;
                            if (!parent || parent.closest(skipTextSelector)) return;
                            const translated = translateValue(node.nodeValue);
                            if (translated !== node.nodeValue) node.nodeValue = translated;
                            return;
                        }
                        if (node.nodeType === Node.ELEMENT_NODE) translateText(node);
                    });
                    if (mutation.type === 'attributes' && mutation.target instanceof Element) {
                        translateAttributes(mutation.target);
                    }
                });
            }).observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['placeholder', 'title', 'aria-label', 'alt', 'data-ai-prompt'] });
        };

        syncLinks();
        syncForms();
        syncLanguageOptions();
        if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initDynamicTranslation);
        else initDynamicTranslation();

        new MutationObserver((mutations) => {
            mutations.forEach((mutation) => {
                mutation.addedNodes.forEach((node) => {
                    if (node.nodeType !== Node.ELEMENT_NODE) return;
                    syncLinks(node);
                    syncForms(node);
                });
            });
        }).observe(document.documentElement, { childList: true, subtree: true });

        if (!requested && preferred !== defaultLocale && current !== preferred) {
            const url = new URL(window.location.href);
            url.searchParams.set('lang', preferred);
            window.location.replace(url.pathname + url.search + url.hash);
        }
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', window.MarocPCInitLanguagePreference);
    } else {
        window.MarocPCInitLanguagePreference();
    }
</script>
HTML;
}

/**
 * Encodes a value to JSON safely for use inside an inline script tag.
 */
function i18n_script_json($value): string
{
    return json_encode($value, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_UNESCAPED_UNICODE);
}
